mapper.select:
SELECT * FROM crowd_source_data 
WHERE trip_id = #{tripId} 
ORDER BY mention_count DESC 
LIMIT #{limit}

mapper.update:
UPDATE crowd_source_data
SET trip_id = #{tripId}, keyword = #{keyword}, source_platform = #{sourcePlatform},
    extracted_item = #{extractedItem}, poi_relation = #{poiRelation}, mention_count = #{mentionCount},
    created_time = #{createdTime}
WHERE id = #{id}
